def safe_divide(a, b):
    try:
        result = a / b
    except ZeroDivisionError:
        print("  cannot divide by zero — returning None")
        return None
    else:
        print("  division succeeded")
        return result
    finally:
        print("  (finally: this always runs)")

print("10/2 ->", safe_divide(10, 2))
print("10/0 ->", safe_divide(10, 0))

