import unittest

class Student:
    def __init__(self, name, id, grades=None):
        self.name = name
        self.id = id
        self.grades = [] if grades is None else grades
    def appendGrade(self, grade):
        self.grades.append(grade)

class TestStudent(unittest.TestCase):
    def test_new_student_has_no_grades(self):
        s = Student("Jack", 123)
        self.assertEqual(s.grades, [])

    def test_append_adds_a_grade(self):
        s = Student("Jane", 456, [90, 95])
        s.appendGrade(80)
        self.assertEqual(s.grades, [90, 95, 80])

suite = unittest.TestLoader().loadTestsFromTestCase(TestStudent)
result = unittest.TextTestRunner(verbosity=2).run(suite)
print("passed:", result.wasSuccessful())

